import {
  Accordion as AccordionPrimitive,
  useAccordion,
  useAccordionContext,
  useAccordionItemContext,
} from '@ark-ui/solid/accordion';
import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { ComponentProps } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { ChevronDownIcon } from '@/lib/moduix/icons/ui';
import styles from './Accordion.module.css';

function Accordion(props: ComponentProps<typeof AccordionPrimitive.Root>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <AccordionPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="accordion-root"
    />
  );
}

function AccordionRootProvider(props: ComponentProps<typeof AccordionPrimitive.RootProvider>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <AccordionPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-slot="accordion-root-provider"
    />
  );
}

function AccordionItem(props: ComponentProps<typeof AccordionPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <AccordionPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="accordion-item"
    />
  );
}

function AccordionItemTrigger(props: ComponentProps<typeof AccordionPrimitive.ItemTrigger>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <AccordionPrimitive.ItemTrigger
      class={clsx(styles.itemTrigger, local.class)}
      {...others}
      data-slot="accordion-item-trigger"
    />
  );
}

function AccordionItemIndicator(props: ComponentProps<typeof AccordionPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['class', 'children']);
  const resolvedChildren = children(() => local.children);

  return (
    <AccordionPrimitive.ItemIndicator
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-slot="accordion-item-indicator"
    >
      {resolvedChildren() ?? <ChevronDownIcon />}
    </AccordionPrimitive.ItemIndicator>
  );
}

function AccordionItemContent(props: ComponentProps<typeof AccordionPrimitive.ItemContent>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <AccordionPrimitive.ItemContent
      class={clsx(styles.itemContent, local.class)}
      {...others}
      data-slot="accordion-item-content"
    />
  );
}

function AccordionItemBody(props: HTMLArkProps<'div'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.div
      class={clsx(styles.itemBody, local.class)}
      {...others}
      data-scope="accordion"
      data-part="item-body"
      data-slot="accordion-item-body"
    />
  );
}

const AccordionContext = AccordionPrimitive.Context;
const AccordionItemContext = AccordionPrimitive.ItemContext;

export {
  Accordion,
  AccordionContext,
  AccordionItem,
  AccordionItemBody,
  AccordionItemContent,
  AccordionItemContext,
  AccordionItemIndicator,
  AccordionItemTrigger,
  AccordionRootProvider,
  useAccordion,
  useAccordionContext,
  useAccordionItemContext,
};
export type {
  AccordionContextProps,
  AccordionFocusChangeDetails,
  AccordionItemContentProps,
  AccordionItemContextProps,
  AccordionItemIndicatorProps,
  AccordionItemProps,
  AccordionItemTriggerProps,
  AccordionRootProps,
  AccordionRootProviderProps,
  AccordionValueChangeDetails,
  UseAccordionContext,
  UseAccordionItemContext,
  UseAccordionProps,
  UseAccordionReturn,
} from '@ark-ui/solid/accordion';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    color: var(--moduix-accordion-color, var(--moduix-color-foreground));

    &[data-orientation='horizontal'] {
      width: auto;
      height: 20rem;
      max-height: 100%;
      flex-direction: row;
    }
  }

  .item {
    overflow-anchor: none;

    &[data-orientation='vertical']:not(:last-child) {
      border-bottom: var(--moduix-accordion-item-border-width, var(--moduix-border-width-sm)) solid
        var(--moduix-accordion-item-border-color, var(--moduix-color-border));
    }

    &[data-orientation='horizontal'] {
      display: flex;

      &:not(:last-child) {
        border-inline-end: var(--moduix-accordion-item-border-width, var(--moduix-border-width-sm))
          solid var(--moduix-accordion-item-border-color, var(--moduix-color-border));
      }
    }
  }

  .itemTrigger {
    box-sizing: border-box;
    display: flex;
    width: 100%;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-accordion-trigger-gap, var(--moduix-spacing-4));
    margin: 0;
    padding-block: var(--moduix-accordion-trigger-padding-y, var(--moduix-spacing-2));
    padding-inline: var(--moduix-accordion-trigger-padding-x, var(--moduix-spacing-3));
    border: 0;
    background-color: var(--moduix-accordion-trigger-bg, transparent);
    color: inherit;
    font: inherit;
    font-size: var(--moduix-accordion-trigger-font-size, var(--moduix-text-md));
    line-height: var(--moduix-line-height-text-md);
    text-align: start;
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    &:not(:is([disabled], [data-disabled])) {
      @media (hover: hover) {
        &:hover {
          background-color: var(--moduix-accordion-trigger-bg-hover, var(--moduix-color-muted));
        }
      }

      &:active {
        background-color: var(--moduix-accordion-trigger-bg-hover, var(--moduix-color-muted));
      }
    }

    &:focus-visible {
      position: relative;
      z-index: 1;
      outline: var(
          --moduix-accordion-focus-ring-width,
          var(--moduix-focus-ring-width, var(--moduix-border-width-md))
        )
        solid var(--moduix-accordion-focus-ring-color, var(--moduix-color-ring));
      outline-offset: calc(
        var(--moduix-accordion-focus-ring-offset, var(--moduix-border-width-sm)) * -1
      );
    }

    &:is([disabled], [data-disabled]) {
      cursor: default;
      opacity: var(--moduix-accordion-disabled-opacity, var(--moduix-opacity-disabled));
    }

    &[data-orientation='horizontal'] {
      width: 2.5rem;
      height: 100%;
      justify-content: center;
      writing-mode: sideways-lr;
    }
  }

  .itemIndicator {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: var(--moduix-accordion-icon-size, var(--moduix-spacing-3));
    height: var(--moduix-accordion-icon-size, var(--moduix-spacing-3));
    flex-shrink: 0;
    transition: transform var(--moduix-transition-default);

    & svg {
      width: 100%;
      height: 100%;
    }

    &[data-state='open'] {
      transform: var(--moduix-accordion-icon-open-transform, rotate(180deg));
    }
  }

  .itemContent {
    box-sizing: border-box;
    overflow: hidden;
    color: var(--moduix-accordion-item-content-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-accordion-item-content-font-size, var(--moduix-text-md));
    line-height: var(--moduix-line-height-text-md);

    &[hidden]:not([hidden='until-found']) {
      display: none;
    }

    &[data-state='open'][data-orientation='vertical'] {
      animation: global(moduix-accordion-item-content-open) var(--moduix-transition-default);
    }

    &[data-state='closed'][data-orientation='vertical'] {
      animation: global(moduix-accordion-item-content-closed) var(--moduix-transition-default);
    }

    &[data-state='open'][data-orientation='horizontal'] {
      animation: global(moduix-accordion-item-content-open-horizontal)
        var(--moduix-transition-default);
    }

    &[data-state='closed'][data-orientation='horizontal'] {
      animation: global(moduix-accordion-item-content-closed-horizontal)
        var(--moduix-transition-default);
    }

    &[data-orientation='horizontal'] > * {
      width: 16rem;
    }
  }

  .itemBody {
    display: grid;
    gap: var(--moduix-accordion-item-body-gap, var(--moduix-spacing-3));
    min-width: 0;
    padding: var(--moduix-accordion-item-body-padding, var(--moduix-spacing-3));
  }

  @media (prefers-reduced-motion: reduce) {
    .itemTrigger,
    .itemIndicator {
      transition: none;
    }

    .itemContent[data-state][data-orientation] {
      animation: none;
    }
  }
}
